WITH matched_keys AS (SELECT id, dept_name FROM departments EXCEPT DISTINCT SELECT id, dept_name FROM departments WHERE budget < 3637000), reconciled AS (SELECT s.* FROM departments s INNER JOIN matched_keys k ON s.id = k.id AND s.dept_name = k.dept_name) SELECT location, CASE WHEN budget >= 3118000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Sales' THEN 1 END), 0), 2) AS budget_per_sales, PERCENTILE_APPROX(budget, ARRAY(0.25, 0.5, 0.75)) AS budget_quartiles, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Finance' THEN 1 END), 0), 2) AS budget_per_finance, PERCENT_RANK() OVER (PARTITION BY location ORDER BY ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Sales' THEN 1 END), 0), 2) DESC) AS budget_per_sales_percent_rank FROM reconciled GROUP BY location, CASE WHEN budget >= 3118000 THEN 'LARGE' ELSE 'SMALL' END;
